module.exports = function (data) {
  // Only rebuild variants when color or size is part of this update (including being cleared)
  const payload = data.$trigger.payload;

  if (!('color' in payload) && !('size' in payload)) {
    throw new Error('No color or size in payload. Returning payload');
  }
};

// Every variant is a [color, size] pair. A product without colors or sizes uses null in that position,
// so the pair lines up with stored variants (which have null in the unused column).
const toList = (value) => (Array.isArray(value) ? value.filter((v) => v !== null && v !== '') : []);

const combinations = (colors, sizes) =>
  (colors.length ? colors : [null]).flatMap((color) => (sizes.length ? sizes : [null]).map((size) => [color, size]));

const sameVariant = (variant, [color, size]) => (variant.color ?? null) === color && (variant.size ?? null) === size;

const createVariant = (productId, [color, size]) => ({
  product: productId,
  color,
  size,
  sku: [color, size].filter(Boolean).map((v) => v.toUpperCase()).join('-') || String(productId).toUpperCase(),
});

const handleProductUpdate = (payload, currentProduct) => {
  if (!currentProduct?.id) {
    throw new Error('Invalid or missing product data');
  }

  // A field in the payload wins, even when it's cleared to null. Otherwise keep the product's current value.
  const colors = toList('color' in payload ? payload.color : currentProduct.color);
  const sizes = toList('size' in payload ? payload.size : currentProduct.size);

  const currentVariants = Array.isArray(currentProduct.variants) ? currentProduct.variants : [];
  const wanted = combinations(colors, sizes);

  // Existing variants that still match are left alone, so their price, weight, image, SKU and id are kept
  const create = wanted
    .filter((combo) => !currentVariants.some((variant) => sameVariant(variant, combo)))
    .map((combo) => createVariant(currentProduct.id, combo));
  const remove = currentVariants
    .filter((variant) => !wanted.some((combo) => sameVariant(variant, combo)))
    .map((variant) => variant.id);

  const variants = {};
  if (create.length > 0) variants.create = create;
  if (remove.length > 0) variants.delete = remove;
  return Object.keys(variants).length > 0 ? { variants } : {};
};

module.exports = function (data) {
  const payload = data.$trigger.payload;
  return {
    ...payload,
    ...handleProductUpdate(payload, data.product),
  };
};

// Every variant is a [color, size] pair, with null in a position the product doesn't use.
const toList = (value) => (Array.isArray(value) ? value.filter((v) => v !== null && v !== '') : []);

const combinations = (colors, sizes) =>
  (colors.length ? colors : [null]).flatMap((color) => (sizes.length ? sizes : [null]).map((size) => [color, size]));

const createVariant = (id, [color, size]) => {
  const sku = [color, size].filter(Boolean).map((v) => v.toUpperCase()).join('-') || (id === undefined ? 'NEW-PRODUCT' : String(id).toUpperCase());
  return { color, size, sku };
};

module.exports = function (data) {
  const payload = data.$trigger.payload;
  const variants = combinations(toList(payload.color), toList(payload.size)).map((combo) => createVariant(payload.id, combo));

  return {
    ...payload,
    variants: {
      create: variants,
    },
  };
};
